"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[73211],{3458:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>i,contentTitle:()=>a,default:()=>m,frontMatter:()=>r,metadata:()=>o,toc:()=>d});var s=n(31085),h=n(71184);const r={sidebar_position:118,slug:"/bible/Psalms/Psalms_118",title:"Psalms 118",hide_table_of_contents:!0},a="Psalms",o={id:"bible/Psalms/Psalms 118",title:"Psalms 118",description:"Chapter 118",source:"@site/docs/bible/Psalms/Psalms 118.md",sourceDirName:"bible/Psalms",slug:"/bible/Psalms/Psalms_118",permalink:"/bibleNotes/docs/bible/Psalms/Psalms_118",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/Psalms/Psalms 118.md",tags:[],version:"current",sidebarPosition:118,frontMatter:{sidebar_position:118,slug:"/bible/Psalms/Psalms_118",title:"Psalms 118",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Psalms 117",permalink:"/bibleNotes/docs/bible/Psalms/Psalms_117"},next:{title:"Psalms 119",permalink:"/bibleNotes/docs/bible/Psalms/Psalms_119"}},i={},d=[{value:"Chapter 118",id:"chapter-118",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,h.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.h1,{id:"psalms",children:"Psalms"}),"\n",(0,s.jsx)(t.h2,{id:"chapter-118",children:"Chapter 118"}),"\n",(0,s.jsx)(t.p,{children:"Beati immaculati. Of the excellence of virtue consisting in the love and observance of the commandments of God. Alleluia. ALEPH."}),"\n",(0,s.jsx)(n,{verse:1,children:"Blessed are the undefiled in the way, who walk in the law of the Lord."}),"\n",(0,s.jsx)(n,{verse:2,children:"Blessed are they that search his testimonies: that seek him with their whole heart."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: His testimonies...The commandments of God are called his testimonies, because they testify his holy will unto us. Note here, that in almost every verse of this psalm (which in number are 176) the word and law of God, and the love and observance of it, is perpetually inculcated, under a variety of denominations, all signifying the same thing."})}),"\n",(0,s.jsx)(n,{verse:3,children:"For they that work iniquity, have not walked in his ways."}),"\n",(0,s.jsx)(n,{verse:4,children:"Thou hast commanded thy commandments to be kept most diligently."}),"\n",(0,s.jsx)(n,{verse:5,children:"O! that my ways may be directed to keep thy justifications."}),"\n",(0,s.jsx)(n,{verse:6,children:"Then shall I not be confounded, when I shall look into all thy commandments."}),"\n",(0,s.jsx)(n,{verse:7,children:"I will praise thee with uprightness of heart, when I shall have learned the judgments of thy justice."}),"\n",(0,s.jsx)(n,{verse:8,children:"I will keep thy justifications: O! do not thou utterly forsake me. BETH."}),"\n",(0,s.jsx)(n,{verse:9,children:"By what doth a young man correct his way? by observing thy words."}),"\n",(0,s.jsx)(n,{verse:10,children:"With my whole heart have I sought after thee: let me not stray from thy commandments."}),"\n",(0,s.jsx)(n,{verse:11,children:"Thy words have I hidden in my heart, that I may not sin against thee."}),"\n",(0,s.jsx)(n,{verse:12,children:"Blessed art thou, O Lord: teach me thy justifications."}),"\n",(0,s.jsx)(n,{verse:13,children:"With my lips I have pronounced all the judgments of thy mouth."}),"\n",(0,s.jsx)(n,{verse:14,children:"I have been delighted in the way of thy testimonies, as in all riches."}),"\n",(0,s.jsx)(n,{verse:15,children:"I will meditate on thy commandments: and I will consider thy ways."}),"\n",(0,s.jsx)(n,{verse:16,children:"I will think of thy justifications: I will not forget thy words. GIMEL."}),"\n",(0,s.jsx)(n,{verse:17,children:"Give bountifully to thy servant, enliven me: and I shall keep thy words."}),"\n",(0,s.jsx)(n,{verse:18,children:"Open thou my eyes: and I will consider the wondrous things of thy law."}),"\n",(0,s.jsx)(n,{verse:19,children:"I am a sojourner on the earth: hide not thy commandments from me."}),"\n",(0,s.jsx)(n,{verse:20,children:"My soul hath coveted to long for thy justifications, at all times."}),"\n",(0,s.jsx)(n,{verse:21,children:"Thou hast rebuked the proud: they are cursed who decline from thy commandments."}),"\n",(0,s.jsx)(n,{verse:22,children:"Remove from me reproach and contempt: because I have sought after thy testimonies."}),"\n",(0,s.jsx)(n,{verse:23,children:"For princes sat, and spoke against me: but thy servant was employed in thy justifications."}),"\n",(0,s.jsx)(n,{verse:24,children:"For thy testimonies are my meditation: and thy justifications my counsel. DALETH."}),"\n",(0,s.jsx)(n,{verse:25,children:"My soul hath cleaved to the pavement: quicken thou me according to thy word."}),"\n",(0,s.jsx)(n,{verse:26,children:"I have declared my ways, and thou hast heard me: teach me thy justifications."}),"\n",(0,s.jsx)(n,{verse:27,children:"Make me to understand the way of thy justifications: and I shall be exercised in thy wondrous works."}),"\n",(0,s.jsx)(n,{verse:28,children:"My soul hath slumbered through heaviness: strengthen thou me in thy words."}),"\n",(0,s.jsx)(n,{verse:29,children:"Remove from me the way of iniquity: and out of thy law have mercy on me."}),"\n",(0,s.jsx)(n,{verse:30,children:"I have chosen the way of truth: thy judgments I have not forgotten."}),"\n",(0,s.jsx)(n,{verse:31,children:"I have stuck to thy testimonies, O Lord: put me not to shame."}),"\n",(0,s.jsx)(n,{verse:32,children:"I have run the way of thy commandments, when thou didst enlarge my heart. HE."}),"\n",(0,s.jsx)(n,{verse:33,children:"Set before me for a law the way of thy justifications, O Lord: and I will always seek after it."}),"\n",(0,s.jsx)(n,{verse:34,children:"Give me understanding, and I will search thy law; and I will keep it with my whole heart."}),"\n",(0,s.jsx)(n,{verse:35,children:"Lead me into the path of thy commandments; for this same I have desired."}),"\n",(0,s.jsx)(n,{verse:36,children:"Incline my heart into thy testimonies and not to covetousness."}),"\n",(0,s.jsx)(n,{verse:37,children:"Turn away my eyes that they may not behold vanity: quicken me in thy way."}),"\n",(0,s.jsx)(n,{verse:38,children:"Establish thy word to thy servant, in thy fear."}),"\n",(0,s.jsx)(n,{verse:39,children:"Turn away my reproach, which I have apprehended: for thy judgments are delightful."}),"\n",(0,s.jsx)(n,{verse:40,children:"Behold I have longed after thy precepts: quicken me in thy justice. VAU."}),"\n",(0,s.jsx)(n,{verse:41,children:"Let thy mercy also come upon me, O Lord: thy salvation according to thy word."}),"\n",(0,s.jsx)(n,{verse:42,children:"So shall I answer them that reproach me in any thing; that I have trusted in thy words."}),"\n",(0,s.jsx)(n,{verse:43,children:"And take not thou the word of truth utterly out of my mouth: for in thy words, I have hoped exceedingly."}),"\n",(0,s.jsx)(n,{verse:44,children:"So shall I always keep thy law, for ever and ever."}),"\n",(0,s.jsx)(n,{verse:45,children:"And I walked at large: because I have sought after thy commandments."}),"\n",(0,s.jsx)(n,{verse:46,children:"And I spoke of thy testimonies before kings: and I was not ashamed."}),"\n",(0,s.jsx)(n,{verse:47,children:"I meditated also on thy commandments, which I loved."}),"\n",(0,s.jsx)(n,{verse:48,children:"And I lifted up my hands to thy commandments, which I loved: and I was exercised in thy justifications. ZAIN."}),"\n",(0,s.jsx)(n,{verse:49,children:"Be thou mindful of thy word to thy servant, in which thou hast given me hope."}),"\n",(0,s.jsx)(n,{verse:50,children:"This hath comforted me in my humiliation: because thy word hath enlivened me."}),"\n",(0,s.jsx)(n,{verse:51,children:"The proud did iniquitously altogether: but I declined not from thy law."}),"\n",(0,s.jsx)(n,{verse:52,children:"I remembered, O Lord, thy judgments of old: and I was comforted."}),"\n",(0,s.jsx)(n,{verse:53,children:"A fainting hath taken hold of me, because of the wicked that forsake thy law."}),"\n",(0,s.jsx)(n,{verse:54,children:"Thy justifications were the subject of my song, in the place of my pilgrimage."}),"\n",(0,s.jsx)(n,{verse:55,children:"In the night I have remembered thy name, O Lord: and have kept thy law."}),"\n",(0,s.jsx)(n,{verse:56,children:"This happened to me: because I sought after thy justifications. HETH."}),"\n",(0,s.jsx)(n,{verse:57,children:"O Lord, my portion, I have said, I would keep thy law."}),"\n",(0,s.jsx)(n,{verse:58,children:"I entreated thy face with all my heart: have mercy on me according to thy word."}),"\n",(0,s.jsx)(n,{verse:59,children:"I have thought on my ways: and turned my feet unto thy testimonies."}),"\n",(0,s.jsx)(n,{verse:60,children:"I am ready, and am not troubled: that I may keep thy commandments."}),"\n",(0,s.jsx)(n,{verse:61,children:"The cords of the wicked have encompassed me: but I have not forgotten thy law."}),"\n",(0,s.jsx)(n,{verse:62,children:"I rose at midnight to give praise to thee; for the judgments of thy justification."}),"\n",(0,s.jsx)(n,{verse:63,children:"I am a partaker with all them that fear thee, and that keep thy commandments."}),"\n",(0,s.jsx)(n,{verse:64,children:"The earth, O Lord, is full of thy mercy: teach me thy justifications. TETH."}),"\n",(0,s.jsx)(n,{verse:65,children:"Thou hast done well with thy servant, O Lord, according to thy word."}),"\n",(0,s.jsx)(n,{verse:66,children:"Teach me goodness and discipline and knowledge; for I have believed thy commandments."}),"\n",(0,s.jsx)(n,{verse:67,children:"Before I was humbled I offended; therefore have I kept thy word."}),"\n",(0,s.jsx)(n,{verse:68,children:"Thou art good; and in thy goodness teach me thy justifications."}),"\n",(0,s.jsx)(n,{verse:69,children:"The iniquity of the proud hath been multiplied over me: but I will seek thy commandments with my whole heart."}),"\n",(0,s.jsx)(n,{verse:70,children:"Their heart is curdled like milk: but I have meditated on thy law."}),"\n",(0,s.jsx)(n,{verse:71,children:"It is good for me that thou hast humbled me, that I may learn thy justifications."}),"\n",(0,s.jsx)(n,{verse:72,children:"The law of thy mouth is good to me, above thousands of gold and silver. JOD."}),"\n",(0,s.jsx)(n,{verse:73,children:"Thy hands have made me and formed me: give me understanding, and I will learn thy commandments."}),"\n",(0,s.jsx)(n,{verse:74,children:"They that fear thee shall see me, and shall be glad : because I have greatly hoped in thy words."}),"\n",(0,s.jsx)(n,{verse:75,children:"I know, O Lord, that thy judgments are equity: and in thy truth thou hast humbled me."}),"\n",(0,s.jsx)(n,{verse:76,children:"O! let thy mercy be for my comfort, according to thy word unto thy servant."}),"\n",(0,s.jsx)(n,{verse:77,children:"Let thy tender mercies come unto me, and I shall live: for thy law is my meditation."}),"\n",(0,s.jsx)(n,{verse:78,children:"Let the proud be ashamed, because they have done unjustly towards me: but I will be employed in thy commandments."}),"\n",(0,s.jsx)(n,{verse:79,children:"Let them that fear thee turn to me: and they that know thy testimonies."}),"\n",(0,s.jsx)(n,{verse:80,children:"Let my heart be undefiled in thy justifications, that I may not be confounded. CAPH."}),"\n",(0,s.jsx)(n,{verse:81,children:"My soul hath fainted after thy salvation: and in thy word I have very much hoped."}),"\n",(0,s.jsx)(n,{verse:82,children:"My eyes have failed for thy word, saying: When wilt thou comfort me?"}),"\n",(0,s.jsx)(n,{verse:83,children:"For I am become like a bottle in the frost: I have not forgotten thy justifications."}),"\n",(0,s.jsx)(n,{verse:84,children:"How many are the days of thy servant: when wilt thou execute judgment on them that persecute me?"}),"\n",(0,s.jsx)(n,{verse:85,children:"The wicked have told me fables: but not as thy law."}),"\n",(0,s.jsx)(n,{verse:86,children:"All thy statutes are truth: they have persecuted me unjustly, do thou help me."}),"\n",(0,s.jsx)(n,{verse:87,children:"They had almost made an end of me upon earth: but I have not forsaken thy commandments."}),"\n",(0,s.jsx)(n,{verse:88,children:"Quicken thou me according to thy mercy: and I shall keep the testimonies of thy mouth. LAMED."}),"\n",(0,s.jsx)(n,{verse:89,children:"For ever, O Lord, thy word standeth firm in heaven."}),"\n",(0,s.jsx)(n,{verse:90,children:"Thy truth unto all generations: thou hast founded the earth, and it continueth."}),"\n",(0,s.jsx)(n,{verse:91,children:"By thy ordinance the day goeth on: for all things serve thee."}),"\n",(0,s.jsx)(n,{verse:92,children:"Unless thy law had been my meditation, I had then perhaps perished in my abjection."}),"\n",(0,s.jsx)(n,{verse:93,children:"Thy justifications I will never forget: for by them thou hast given me life."}),"\n",(0,s.jsx)(n,{verse:94,children:"I am thine, save thou me: for I have sought thy justifications."}),"\n",(0,s.jsx)(n,{verse:95,children:"The wicked have waited for me to destroy me: but I have understood thy testimonies."}),"\n",(0,s.jsx)(n,{verse:96,children:"I have seen an end of all perfection: thy commandment is exceeding broad. MEM."}),"\n",(0,s.jsx)(n,{verse:97,children:"O how have I loved thy law, O Lord! it is my meditation all the day."}),"\n",(0,s.jsx)(n,{verse:98,children:"Through thy commandment, thou hast made me wiser than my enemies: for it is ever with me."}),"\n",(0,s.jsx)(n,{verse:99,children:"I have understood more than all my teachers: because thy testimonies are my meditation."}),"\n",(0,s.jsx)(n,{verse:100,children:"I have had understanding above ancients: because I have sought thy commandments."}),"\n",(0,s.jsx)(n,{verse:101,children:"I have restrained my feet from every evil way: that I may keep thy words."}),"\n",(0,s.jsx)(n,{verse:102,children:"I have not declined from thy judgments, because thou hast set me a law."}),"\n",(0,s.jsx)(n,{verse:103,children:"How sweet are thy words to my palate! more than honey to my mouth."}),"\n",(0,s.jsx)(n,{verse:104,children:"By thy commandments I have had understanding: therefore have I hated every way of iniquity. NUN."}),"\n",(0,s.jsx)(n,{verse:105,children:"Thy word is a lamp to my feet, and a light to my paths."}),"\n",(0,s.jsx)(n,{verse:106,children:"I have sworn and am determined to keep the judgments of thy justice."}),"\n",(0,s.jsx)(n,{verse:107,children:"I have been humbled, O Lord, exceedingly: quicken thou me according to thy word."}),"\n",(0,s.jsx)(n,{verse:108,children:"The free offerings of my mouth make acceptable, O Lord: and teach me thy judgments."}),"\n",(0,s.jsx)(n,{verse:109,children:"My soul is continually in my hands: and I have not forgotten thy law."}),"\n",(0,s.jsx)(n,{verse:110,children:"Sinners have laid a snare for me: but I have not erred from thy precepts."}),"\n",(0,s.jsx)(n,{verse:111,children:"I have purchased thy testimonies for an inheritance for ever: because they are the joy of my heart."}),"\n",(0,s.jsx)(n,{verse:112,children:"I have inclined my heart to do thy justifications for ever, for the reward. SAMECH."}),"\n",(0,s.jsx)(n,{verse:113,children:"I have hated the unjust: and have loved thy law."}),"\n",(0,s.jsx)(n,{verse:114,children:"Thou art my helper and my protector: and in thy word I have greatly hoped."}),"\n",(0,s.jsx)(n,{verse:115,children:"Depart from me, ye malignant: and I will search the commandments of my God."}),"\n",(0,s.jsx)(n,{verse:116,children:"Uphold me according to thy word, and I shall live: and let me not be confounded in my expectation."}),"\n",(0,s.jsx)(n,{verse:117,children:"Help me, and I shall be saved: and I will meditate always on thy justifications."}),"\n",(0,s.jsx)(n,{verse:118,children:"Thou hast despised all them that fall off from thy judgments; for their thought is unjust."}),"\n",(0,s.jsx)(n,{verse:119,children:"I have accounted all the sinners of the earth prevaricators: therefore have I loved thy testimonies."}),"\n",(0,s.jsx)(n,{verse:120,children:"Pierce thou my flesh with thy fear: for I am afraid of thy judgments. AIN."}),"\n",(0,s.jsx)(n,{verse:121,children:"I have done judgment and justice: give me not up to them that slander me."}),"\n",(0,s.jsx)(n,{verse:122,children:"Uphold thy servant unto good: let not the proud calumniate me."}),"\n",(0,s.jsx)(n,{verse:123,children:"My eyes have fainted after thy salvation: and for the word of thy justice."}),"\n",(0,s.jsx)(n,{verse:124,children:"Deal with thy servant according to thy mercy: and teach me thy justifications."}),"\n",(0,s.jsx)(n,{verse:125,children:"I am thy servant: give me understanding that I may know thy testimonies."}),"\n",(0,s.jsx)(n,{verse:126,children:"It is time, O Lord, to do: they have dissipated thy law."}),"\n",(0,s.jsx)(n,{verse:127,children:"Therefore have I loved thy commandments above gold and the topaz."}),"\n",(0,s.jsx)(n,{verse:128,children:"Therefore was I directed to all thy commandments: I have hated all wicked ways. PHE."}),"\n",(0,s.jsx)(n,{verse:129,children:"Thy testimonies are wonderful: therefore my soul hath sought them."}),"\n",(0,s.jsx)(n,{verse:130,children:"The declaration of thy words giveth light: and giveth understanding to little ones."}),"\n",(0,s.jsx)(n,{verse:131,children:"I opened my mouth, and panted: because I longed for thy commandments."}),"\n",(0,s.jsx)(n,{verse:132,children:"Look thou upon me, and have mercy on me according to the judgment of them that love thy name."}),"\n",(0,s.jsx)(n,{verse:133,children:"Direct my steps according to thy word: and let no iniquity have dominion over me."}),"\n",(0,s.jsx)(n,{verse:134,children:"Redeem me from the calumnies of men: that I may keep thy commandments."}),"\n",(0,s.jsx)(n,{verse:135,children:"Make thy face to shine upon thy servant: and teach me thy justifications."}),"\n",(0,s.jsx)(n,{verse:136,children:"My eyes have sent forth springs of water: because they have not kept thy law. SADE."}),"\n",(0,s.jsx)(n,{verse:137,children:"Thou art just, O Lord: and thy judgment is right."}),"\n",(0,s.jsx)(n,{verse:138,children:"Thou hast commanded justice thy testimonies: and thy truth exceedingly."}),"\n",(0,s.jsx)(n,{verse:139,children:"My zeal hath made me pine away: because my enemies forgot thy words."}),"\n",(0,s.jsx)(n,{verse:140,children:"Thy word is exceedingly refined: and thy servant hath loved it."}),"\n",(0,s.jsx)(n,{verse:141,children:"I am very young and despised; but I forget not thy justifications."}),"\n",(0,s.jsx)(n,{verse:142,children:"Thy justice is justice for ever: and thy law is the truth."}),"\n",(0,s.jsx)(n,{verse:143,children:"Trouble and anguish have found me: thy commandments are my meditation."}),"\n",(0,s.jsx)(n,{verse:144,children:"Thy testimonies are justice for ever: give me understanding, and I shall live. COPH."}),"\n",(0,s.jsx)(n,{verse:145,children:"I cried with my whole heart, hear me, O Lord: I will seek thy justifications."}),"\n",(0,s.jsx)(n,{verse:146,children:"I cried unto thee, save me: that I may keep thy commandments."}),"\n",(0,s.jsx)(n,{verse:147,children:"I prevented the dawning of the day, and cried: because in thy words I very much hoped."}),"\n",(0,s.jsx)(n,{verse:148,children:"My eyes to thee have prevented the morning: that I might meditate on thy words."}),"\n",(0,s.jsx)(n,{verse:149,children:"Hear thou my voice, O Lord, according to thy mercy: and quicken me according to thy judgment."}),"\n",(0,s.jsx)(n,{verse:150,children:"They that persecute me have drawn nigh to iniquity; but they are gone far off from thy law."}),"\n",(0,s.jsx)(n,{verse:151,children:"Thou art near, O Lord: and all thy ways are truth."}),"\n",(0,s.jsx)(n,{verse:152,children:"I have known from the beginning concerning thy testimonies: that thou hast founded them for ever. RES."}),"\n",(0,s.jsx)(n,{verse:153,children:"See my humiliation and deliver me for I have not forgotten thy law."}),"\n",(0,s.jsx)(n,{verse:154,children:"Judge my judgment and redeem me: quicken thou me for thy word's sake."}),"\n",(0,s.jsx)(n,{verse:155,children:"Salvation is far from sinners; because they have not sought thy justifications."}),"\n",(0,s.jsx)(n,{verse:156,children:"Many, O Lord, are thy mercies: quicken me according to thy judgment."}),"\n",(0,s.jsx)(n,{verse:157,children:"Many are they that persecute me and afflict me; but I have not declined from thy testimonies."}),"\n",(0,s.jsx)(n,{verse:158,children:"I beheld the transgressors, and pined away; because they kept not thy word."}),"\n",(0,s.jsx)(n,{verse:159,children:"Behold I have loved thy commandments, O Lord; quicken me thou in thy mercy."}),"\n",(0,s.jsx)(n,{verse:160,children:"The beginning of thy words is truth: all the judgments of thy justice are for ever. SIN."}),"\n",(0,s.jsx)(n,{verse:161,children:"Princes have persecuted me without cause: and my heart hath been in awe of thy words."}),"\n",(0,s.jsx)(n,{verse:162,children:"I will rejoice at thy words, as one that hath found great spoil."}),"\n",(0,s.jsx)(n,{verse:163,children:"I have hated and abhorred iniquity; but I have loved thy law."}),"\n",(0,s.jsx)(n,{verse:164,children:"Seven times a day I have given praise to thee, for the judgments of thy justice."}),"\n",(0,s.jsx)(n,{verse:165,children:"Much peace have they that love thy law, and to them there is no stumbling. block."}),"\n",(0,s.jsx)(n,{verse:166,children:"I looked for thy salvation, O Lord: and I loved thy commandments."}),"\n",(0,s.jsx)(n,{verse:167,children:"My soul hath kept thy testimonies and hath loved them exceedingly."}),"\n",(0,s.jsx)(n,{verse:168,children:"I have kept thy commandments and thy testimonies: because all my ways are in thy sight. TAU."}),"\n",(0,s.jsx)(n,{verse:169,children:"Let my supplication, O Lord, come near in thy sight: give me understanding according to thy word."}),"\n",(0,s.jsx)(n,{verse:170,children:"Let my request come in before thee; deliver thou me according to thy word."}),"\n",(0,s.jsx)(n,{verse:171,children:"My lips shall utter a hymn, when thou shalt teach me thy justifications."}),"\n",(0,s.jsx)(n,{verse:172,children:"My tongue shall pronounce thy word: because all thy commandments are justice."}),"\n",(0,s.jsx)(n,{verse:173,children:"Let thy hand be with me to save me; for I have chosen thy precepts."}),"\n",(0,s.jsx)(n,{verse:174,children:"I have longed for thy salvation, O Lord; and thy law is my meditation."}),"\n",(0,s.jsx)(n,{verse:175,children:"My soul shall live and shall praise thee: and thy judgments shall help me."}),"\n",(0,s.jsx)(n,{verse:176,children:"I have gone astray like a sheep that is lost: seek thy servant, because I have not forgotten thy commandments."})]})}function m(e={}){const{wrapper:t}={...(0,h.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>a,x:()=>o});var s=n(14041);const h={},r=s.createContext(h);function a(e){const t=s.useContext(r);return s.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(h):e.components||h:a(e.components),s.createElement(r.Provider,{value:t},e.children)}}}]);